B.ajb=new A.hu("cikmaci_ibo","\xc7IKMA PAR\xc7A \u0130ND\u0130R\u0130M\u0130","\xc7\u0131kmac\u0131 \u0130bo","Yedek Par\xe7a Baronu","bolt",B.dc,"\u201cAlmanya\u2019dan t\u0131r dolusu orijinal s\u0131f\u0131r ayar\u0131nda yedek par\xe7a indirdim! \xc7\u0131raklara ufak bir destek atarsan at\xf6lye masraflar\u0131n i\xe7in sana \u20ba35.000 de\u011ferinde par\xe7a kredisi hibe ediyorum!\u201d","At\xf6lye tamirat ve yedek par\xe7a kasana \u20ba35.000 nakit hibe eklenir.","PAR\xc7A KRED\u0130S\u0130N\u0130 AL (REKLAMI \u0130ZLE)","Orijinal Par\xe7adan \u015ea\u015fmam",B.Jv,null)
